const source = $json.body ?? $json;

const fields = [
  'nome',
  'whatsapp',
  'cidade_estado',
  'plataforma',
  'conteudo_no_ar',
  'possui_provas',
  'prejuizo',
  'relato',
  'origem',
  'utm_source',
  'utm_medium',
  'utm_campaign',
  'utm_content',
  'utm_term',
];

const data = {};
for (const field of fields) {
  const value = source[field];
  data[field] = value === undefined || value === null ? '' : String(value).trim();
}

data.data_entrada = new Date().toISOString();
data.whatsapp = data.whatsapp.replace(/\D/g, '');
data.status = 'Novo';
data.origem = data.origem || 'site_google_ads';

const missing = ['nome', 'whatsapp', 'relato'].filter((field) => !data[field]);

if (missing.length > 0) {
  return [
    {
      json: {
        success: false,
        validation_error: true,
        missing_fields: missing,
        message: 'Algumas informações obrigatórias não foram enviadas. Verifique nome, WhatsApp e relato.',
        data_entrada: data.data_entrada,
      },
    },
  ];
}

return [
  {
    json: {
      success: true,
      ...data,
    },
  },
];

