const lead = $items('Code | Normalizar Dados', 0, 0)[0]?.json ?? {};
const aiRaw = $input.first().json;

function extractAiPayload(raw) {
  if (raw && raw.resumo_ia) {
    return raw;
  }

  let content = raw?.message?.content
    ?? raw?.choices?.[0]?.message?.content
    ?? raw?.data?.choices?.[0]?.message?.content
    ?? raw?.text
    ?? raw?.output
    ?? raw?.content
    ?? '';

  if (typeof content !== 'string') {
    content = JSON.stringify(content);
  }

  const cleaned = content.replace(/```json/gi, '').replace(/```/g, '').trim();

  try {
    return JSON.parse(cleaned);
  } catch (error) {
    return {
      resumo_ia: cleaned || 'Resumo não retornado pela IA.',
      classificacao: 'medio',
      urgencia: 'media',
      tipo_caso: 'Triagem digital',
      proximo_passo: 'Revisar manualmente as informações e solicitar documentos ou provas complementares, se necessário.',
    };
  }
}

const ai = extractAiPayload(aiRaw);
const allowedClassificacao = ['quente', 'medio', 'frio'];
const allowedUrgencia = ['alta', 'media', 'baixa'];

return [
  {
    json: {
      data_entrada: lead.data_entrada ?? new Date().toISOString(),
      nome: lead.nome ?? '',
      whatsapp: lead.whatsapp ?? '',
      cidade_estado: lead.cidade_estado ?? '',
      plataforma: lead.plataforma ?? '',
      conteudo_no_ar: lead.conteudo_no_ar ?? '',
      possui_provas: lead.possui_provas ?? '',
      prejuizo: lead.prejuizo ?? '',
      relato: lead.relato ?? '',
      origem: lead.origem ?? 'site_google_ads',
      utm_source: lead.utm_source ?? '',
      utm_medium: lead.utm_medium ?? '',
      utm_campaign: lead.utm_campaign ?? '',
      utm_content: lead.utm_content ?? '',
      utm_term: lead.utm_term ?? '',
      resumo_ia: ai.resumo_ia ?? '',
      classificacao: allowedClassificacao.includes(ai.classificacao) ? ai.classificacao : 'medio',
      urgencia: allowedUrgencia.includes(ai.urgencia) ? ai.urgencia : 'media',
      tipo_caso: ai.tipo_caso ?? '',
      proximo_passo: ai.proximo_passo ?? '',
      status: lead.status ?? 'Novo',
    },
  },
];

